497	//   - rules: list of policy rules for the cluster role
498	func BuildClusterRole(name, ownerName string, rules []rbacv1.PolicyRule) *rbacv1.ClusterRole {
499		return &rbacv1.ClusterRole{
500			ObjectMeta: metav1.ObjectMeta{
501				Name: name,
502				Labels: map[string]string{
503					AggregationLabel:        name,
504					ClusterRoleOwnerLabel:   ownerName,
505					AggregationFeatureLabel: "true",
506				},
507			},
508			Rules: rules,
