512	// BuildAggregatingClusterRole returns a ClusterRole with AggregationRules
513	//   - rt the role template to base it off of. Most importantly, it adds an aggregation label for each role template in RoleTemplateNames
514	//   - nameTransformer a function that takes a string and returns one that represents the cluster role name. It also applies to all inherited role templates.
515	func BuildAggregatingClusterRole(rt *v3.RoleTemplate, nameTransformer func(string) string) *rbacv1.ClusterRole {
516		crName := nameTransformer(rt.Name)
517		ownerName := rt.Name
518	
519		// aggregate our own cluster role
520		roleTemplateLabels := []metav1.LabelSelector{{MatchLabels: map[string]string{AggregationLabel: crName}}}
521	
522		// aggregate every inherited role template
523		for _, roleTemplateName := range rt.RoleTemplateNames {
524			labelSelector := metav1.LabelSelector{
525				MatchLabels: map[string]string{AggregationLabel: AggregatedClusterRoleNameFor(nameTransformer(roleTemplateName))},
526			}
527			roleTemplateLabels = append(roleTemplateLabels, labelSelector)
528		}
529	
530		aggregatingCRName := AggregatedClusterRoleNameFor(crName)
531		return &rbacv1.ClusterRole{
532			ObjectMeta: metav1.ObjectMeta{
533				Name: aggregatingCRName,
534				Labels: map[string]string{
535					// Label so other cluster roles can aggregate this one
536					AggregationLabel: aggregatingCRName,
537					// Label to identify who owns this cluster role
538					ClusterRoleOwnerLabel:   ownerName,
539					AggregationFeatureLabel: "true",
540				},
541			},
542			AggregationRule: &rbacv1.AggregationRule{
543				ClusterRoleSelectors: roleTemplateLabels,
544			},
545		}
546	}
