189		if len(rules) != 0 {
190			return []*rbacv1.ClusterRole{
191				rbac.BuildClusterRole(crNameTransformer(rtName), rtName, rules),
192				rbac.BuildAggregatingClusterRole(rt, crNameTransformer),
193			}, nil
194		}
195	
196		ok, err := r.areThereInheritedManagementPlaneRules(rt.RoleTemplateNames, crNameTransformer)
197		if err != nil {
198			return nil, err
199		}
200		if ok {
201			return []*rbacv1.ClusterRole{rbac.BuildAggregatingClusterRole(rt, crNameTransformer)}, nil
202		}
203	
204		return nil, nil
205	}
