209	func (r *roleTemplateHandler) areThereInheritedManagementPlaneRules(inheritedRoleTemplates []string, crNameTransformer func(string) string) (bool, error) {
210		for _, rt := range inheritedRoleTemplates {
211			_, err := r.crController.Get(rbac.AggregatedClusterRoleNameFor(crNameTransformer(rt)), metav1.GetOptions{})
212			if err == nil {
213				return true, nil
214			} else if !apierrors.IsNotFound(err) {
215				return false, err
216			}
217		}
218		return false, nil
219	}
