118	// buildPromotedClusterRoles looks for promoted rules in a project role template and creates required promoted cluster roles.
119	// It also returns the role template rules with the promoted rules removed.
120	func (rth *roleTemplateHandler) buildPromotedClusterRoles(rt *v3.RoleTemplate) ([]*rbacv1.ClusterRole, error) {
121		clusterRoles := []*rbacv1.ClusterRole{}
